#include <iostream>
#include <string>
bool parseByte(const std::string& token, unsigned int& value) {
    if (token.empty()) return false;
    value = 0u;
    for (char ch : token) {
        // 토큰 전체가 부호 없는 ASCII 십진 숫자인지 검사합니다.
        if (ch < '0' || ch > '9') return false;
        const unsigned int digit = static_cast<unsigned int>(ch - '0');
        if (value > (255u - digit) / 10u) return false;
        value = value * 10u + digit;
    }
    return true;
}
int main() {
    std::string tokenA, tokenB, extra;
    unsigned int a = 0u, b = 0u;
    // 공백으로 나뉜 두 토큰을 각각 끝까지 해석합니다.
    if (!(std::cin >> tokenA >> tokenB) || (std::cin >> extra)) return 1;
    if (!parseByte(tokenA, a) || !parseByte(tokenB, b)) return 1;
    while (b != 0u) {
        // 이전 두 값을 모두 사용한 뒤 새 상태로 바꿉니다.
        const unsigned int carry = ((a & b) << 1u) & 255u;
        const unsigned int withoutCarry = (a ^ b) & 255u;
        a = withoutCarry;
        b = carry;
    }
    std::cout << a << '\n';
}
